             "assert h.u16(0x0224A7F0, 'ov3') == 0x7960, 'ldrb r0,[r4,#5] drifted'\n"
             "assert h.u16(0x0224A7F2, 'ov3') == 0x2801, 'cmp r0,#1 (selector) drifted'\n"
             "assert h.u16(0x0224A7F6, 'ov3') == 0x7920, 'ldrb r0,[r4,#4] drifted'\n"
             "assert h.u16(0x0224A7F8, 'ov3') == 0x2806, 'cmp r0,#6 (event code) drifted'\n"
             "assert h.u16(0x0224A7FC, 'ov3') == 0x2001, 'movs r0,#1 (offset=1) drifted'\n"
             "assert h.u16(0x0224A802, 'ov3') == 0x2000, 'movs r0,#0 (offset=0) drifted'\n"
