             assert h.u16(0x021D318E, 'ov3') == 0x0FC0, 'the `lsrs r0,r0,#0x1f` moved'
             assert h.u16(0x021D3190, 'ov3') == 0x70A0, 'the `strb r0,[r4,#2]` moved'
