             assert h.u16(0x021B0806, 'ov3') == 0x2001, '0x021B0806 is not `movs r0,#1`'
             assert h.u16(0x021B0808, 'ov3') == 0x1A40, '0x021B0808 is not `subs r0,r0,r1`'
             assert h.u16(0x021B080A, 'ov3') == 0x4286, '0x021B080A is not `cmp r6,r0`'
