             assert h.u16(0x021D6D42, 'ov3') == 0x6DC1, 'guard 2 is not ldr r1,[r0,#0x5C]'
             assert h.u16(0x021D6D4E, 'ov3') == 0x6E40, 'guard 3 is not ldr r0,[r0,#0x64]'
             assert h.u16(0x021D6D68, 'ov3') == 0x6D40, 'guard 5 is not ldr r0,[r0,#0x54]'
