             assert h.u16(0x0223A1C8, 'ov3') == 0x6DE0, 'state load is not ldr r0,[r4,#0x5C]'
             assert h.u16(0x0223A1CA, 'ov3') == 0x2803, '0x0223A1CA is not cmp r0,#3'
