             POP = ['PUSH {R3, LR}', 'LDR R1, [PC, #0x40]', 'LDR R0, [R1, #0x34]', 'CMP R0, #0x0', 'BNE 0x021D29A6', 'LDR R0, [PC, #0x3C]', 'LDR R2, [R0, #0x64]', 'CMP R2, #0x0', 'BEQ 0x021D2982', 'LDR R0, [R0, #0x38]', 'LSL R2, R0, #2', 'LDR R0, [PC, #0x34]', 'LDR R0, [R0, R2]', 'CMP R0, #0x2', 'BEQ 0x021D298C', 'LDR R0, [PC, #0x24]', 'LDR R1, [R0, #0x28]', 'SUB R1, R1, #0x1', 'STR R1, [R0, #0x28]', 'POP {R3, PC}', 'MOV R2, #0x0', 'ADD R0, SP, #0x0', 'STRH R2, [R0, #0x0]', 'LDR R0, [R1, #0x28]', 'ADD R2, SP, #0x0', 'SUB R0, R0, #0x1', 'STR R0, [R1, #0x28]', 'MOV R1, #0x8', 'MOV R0, #0x8', 'SUB R1, #0x9', 'MOV R3, #0x2', 'BL 0x0219EA84', 'POP {R3, PC}']
             assert code(0x021D28A4, 0x021D28FA) == PUSH, 'push body changed'
