             assert dec(0x021A36EC, 0x021A36F2) == ['ldr r3, [pc, #4]', 'movs r2, #1', 'bx r3'], 'thunk changed'
             assert h.u32(0x021A36F4, 'ov3') == 0x021A36F9, 'thunk target moved'
             BODY = ['push {r1, r2, r3, r4, r5, r6, r7, lr}', 'adds r5, r1, #0', 'str r2, [sp]', 'movs r2, #0x14', 'adds r6, r5, #0', 'muls r6, r2, r6', 'adds r7, r0, #0', 'movs r2, #1', 'ldr r3, [pc, #0xa8]', 'ands r2, r7', 'muls r3, r2, r3', 'str r3, [sp, #4]', 'ldr r3, [pc, #0xa4]', 'ldr r2, [sp, #4]', 'adds r2, r3, r2', 'adds r2, r2, r6', 'ldr r2, [r2, #0x34]', 'lsls r2, r2, #0x12', 'lsrs r4, r2, #0x12', 'cmp r5, #4', 'bgt #0x21a379e', 'adds r0, r4, #0', 'bl #0x2023640', 'cmp r0, #0', 'beq #0x21a377c', 'ldr r1, [pc, #0x8c]', 'ldr r0, [sp, #4]', 'ldr r7, [pc, #0x8c]', 'adds r0, r1, r0', 'ldrh r6, [r6, r0]', 'b #0x21a3776', 'movs r0, #0xa', 'adds r1, r6, #0', 'muls r1, r0, r1', 'ldr r0, [pc, #0x84]', 'adds r5, r0, r1', 'ldrh r0, [r5, #2]', 'ldrh r6, [r5, #8]', 'lsls r0, r0, #0x1c', 'lsrs r0, r0, #0x1c', 'cmp r0, #2', 'beq #0x21a3758', 'cmp r0, #3', 'bne #0x21a3776', 'ldrh r0, [r5]', 'cmp r0, r7', 'bne #0x21a3776', 'ldrh r1, [r5]', 'ldr r0, [pc, #0x6c]', 'cmp r1, r0', 'beq #0x21a376a', 'ldr r0, [pc, #0x68]', 'cmp r1, r0', 'beq #0x21a376a', 'cmp r1, r7', 'bne #0x21a3776', 'ldrh r0, [r5, #4]', 'bl #0x2029e60', 'cmp r0, #0', 'beq #0x21a3776', 'ldrh r4, [r5, #4]', 'cmp r6, #0', 'bne #0x21a3738', 'b #0x21a37b0', 'ldr r0, [sp]', 'cmp r0, #0', 'beq #0x21a37b0', 'adds r0, r4, #0', 'bl #0x2023b00', 'cmp r0, #0', 'beq #0x21a37b0', 'ldr r2, [pc, #0x40]', 'adds r0, r7, #0', 'adds r1, r5, #0', 'bl #0x21a1584', 'cmp r0, #0', 'ble #0x21a37b0', 'adds r4, r0, #0', 'b #0x21a37b0', 'ldr r5, [pc, #0x34]', 'cmp r4, r5', 'bne #0x21a37b0', 'adds r2, r5, #0', 'bl #0x21a1584', 'adds r4, r0, #0', 'bpl #0x21a37b0', 'adds r4, r5, #0', 'adds r0, r4, #0', 'pop {r1, r2, r3, r4, r5, r6, r7, pc}']
             assert dec(0x021A36F8, 0x021A37B4) == BODY, 'body changed'
             assert [h.u32(0x021A37B4 + 4 * k, 'ov3') for k in range(9)] == [0x0B3C, 0x0229AC94, 0x0229ACD2, 0x221E, 0x0229D33C, 0x1A74, 0x1E7E, 0x1DDA, 0x2150]
