    # ---- 2026-10-18 batch: small high-fan-in ov3 helpers (thunks and predicates), each body asserted from the stock bytes ----
    def _thumb_fact(fid, addr, end, expect, pools, claim, extra=''):
        """expect = exact capstone-Thumb decode of [addr, end); pools = [(addr, value), ...]."""
        proof = (
            "import capstone\n"
            "md = capstone.Cs(capstone.CS_ARCH_ARM, capstone.CS_MODE_THUMB)\n"
            f"got = [(i.mnemonic + ' ' + i.op_str) for i in md.disasm(h.bytes_at({addr:#x}, {end - addr:#x}, 'ov3'), {addr:#x})]\n"
            f"assert got == {expect!r}, 'body changed'\n"
            + ''.join(f"assert h.u32({a:#x}, 'ov3') == {v:#x}, 'pool word moved'\n" for a, v in pools)
            + extra)
        verified(fid, 'effect_dispatch_tables', claim, proof,
                 ['notes/ov3-catalogue-findings.md'], addr=addr, oracle='ov3')

