    _HDR_C = """
    import hashlib, capstone
    md = capstone.Cs(capstone.CS_ARCH_ARM, capstone.CS_MODE_THUMB)
    def dec(a, e):
        return [(i.mnemonic + ' ' + i.op_str) for i in md.disasm(h.bytes_at(a, e - a, 'ov3'), a)]
    def sha(a, e, n, d):
        b = dec(a, e)
        assert len(b) == n, len(b)
        assert hashlib.sha256(chr(10).join(b).encode()).hexdigest() == d, 'body changed'
    """
