             assert [h.u32(0x021A357C + 4 * k, 'ov3') for k in range(26)] == [0xB3C, 0x229AC94, 0x229ACD2, 0x1E7E, 0x221E, 0x1FA9, 0x229D33C, 0x1A74, 0x1D43, 0x24DC, 0x26B0, 0x229ACCC,
                 0x1BC7, 0x19A6, 0xEA9, 0x1E6C, 0x2269, 0x229ACD4, 0xFE4, 0x19FD, 0x1918, 0xECD, 0x2150, 0x229ACD8, 0x12BE, 0x10F4]
