# ---------------------------------------------------------------------------
# YAML emission
# ---------------------------------------------------------------------------
def _yaml_str(s: str) -> str:
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _emit_value(v) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return f"0x{v:08X}" if v > 0xFFFF else f"0x{v:04X}"
    if isinstance(v, list):
        return "[" + ", ".join(str(x) for x in v) + "]"
    return _yaml_str(str(v))


_KEY_ORDER = ["id", "subsystem", "confidence", "claim", "address", "oracle",
              "sources", "next_experiment", "corrected_by", "proof"]


def _emit_fact(d: dict) -> str:
    lines = []
    first = True
    for k in _KEY_ORDER:
        if k not in d or d[k] is None:
            continue
        prefix = "- " if first else "  "
        first = False
        if k == "proof":
            lines.append(f"  proof: |")
            for pl in d[k].rstrip("\n").split("\n"):
                lines.append(f"    {pl}" if pl else "")
        else:
            lines.append(f"{prefix}{k}: {_emit_value(d[k])}")
    return "\n".join(lines) + "\n"


def _capture(env) -> list[dict]:
    """Resolve builder records into final YAML dicts, capturing anchor signatures."""
    from otn_enhanced.knowledge.helpers import Helpers
    h = Helpers(env)
    out = []
    for f in _FACTS:
        d = {k: f[k] for k in ("id", "subsystem", "confidence", "claim",
                               "address", "oracle", "sources", "next_experiment",
                               "corrected_by") if f.get(k) is not None}
        kind = f["_kind"]
        if kind == "anchor":
            addr, oracle, n = f["address"], f["oracle"], f["_n"]
            if env.oracle_name(addr) != oracle:
                # stale / typo address — cannot anchor; degrade honestly
                d["confidence"] = "UNVERIFIED"
                d["next_experiment"] = (f.get("next_experiment") or
                                        f"address 0x{addr:08X} is not in oracle '{oracle}'; re-locate it.")
            else:
                sig = h.bytes_at(addr, n, oracle).hex()
                d["proof"] = (f"sig = h.bytes_at(0x{addr:08X}, {n}, '{oracle}')\n"
                              f"assert sig == bytes.fromhex('{sig}'), "
                              f"'0x{addr:08X} signature drifted'\n")
                if f.get("next_experiment"):
                    d["next_experiment"] = f["next_experiment"]
        elif kind == "proof":
            d["proof"] = f["proof"]
        out.append(d)
    return out


def generate(check: bool = False) -> None:
    _FACTS.clear()
    _declare()
    env = load_env()
    facts = _capture(env)

    DOCS_ENGINE.mkdir(parents=True, exist_ok=True)
    by_sub: dict[str, list[dict]] = {}
    for d in facts:
        by_sub.setdefault(d["subsystem"], []).append(d)

    for sub in sorted(by_sub):
        path = DOCS_ENGINE / f"{sub}.yaml"
        body = [f"# {sub} — engine facts (generated by author_facts.py; edit there, then regenerate)",
                f"# grading: VERIFIED (closed proof) | ANCHORED (captured signature) | UNVERIFIED (needs experiment)",
                ""]
        for d in by_sub[sub]:
            body.append(_emit_fact(d))
        path.write_text("\n".join(body), encoding="utf-8")
        print(f"wrote {path.relative_to(DOCS_ENGINE.parents[1])}  ({len(by_sub[sub])} facts)")

    print(f"\nTotal: {len(facts)} facts in {len(by_sub)} subsystems.")

    if check:
        from otn_enhanced.knowledge.loader import load_facts, run_all
        results = run_all(env, load_facts())
        p = sum(r.status == "PASS" for r in results)
        fl = sum(r.status == "FAIL" for r in results)
        u = sum(r.status == "UNVERIFIED" for r in results)
        print(f"self-check: {p} PASS  {fl} FAIL  {u} UNVERIFIED")
        for r in results:
            if r.status == "FAIL":
                print(f"  FAIL {r.fact.id}: {r.message}")


if __name__ == "__main__":
    import sys
    generate(check="--check" in sys.argv)
